139:     const auto browserRequest = decodeRequest(json);
140:     if (browserRequest.isEmpty()) {
141:         return getErrorReply(action, ERROR_KEEPASS_CANNOT_DECRYPT_MESSAGE);
142:     }
143: 
144:     if (browserRequest.hash.isEmpty()) {
145:         return getErrorReply(action, ERROR_KEEPASS_DATABASE_HASH_NOT_RECEIVED);
146:     }
147: 
148:     const auto command = browserRequest.getString("action");
149:     if (!command.isEmpty() && command.compare(BROWSER_REQUEST_GET_DATABASEHASH) == 0) {
150:         auto message = browserMessageBuilder()->buildMessage(browserRequest.incrementedNonce);
151:         message["hash"] = browserRequest.hash;
152: 
153:         // Update a legacy database hash if found
154:         const auto hashes = browserRequest.getArray("connectedKeys");
155:         if (!hashes.isEmpty()) {
156:             const auto legacyHash = browserService()->getDatabaseHash(true);
157:             if (hashes.contains(legacyHash)) {
158:                 message["oldHash"] = legacyHash;
159:             }
160:         }
161: 
162:         return buildResponse(action, message, browserRequest.incrementedNonce);
163:     }
164: 
165:     return getErrorReply(action, ERROR_KEEPASS_CANNOT_DECRYPT_MESSAGE);
166: }
