168: QJsonObject BrowserAction::handleAssociate(const QJsonObject& json, const QString& action)
169: {
170:     const auto browserRequest = decodeRequest(json);
171:     if (browserRequest.isEmpty()) {
172:         return getErrorReply(action, ERROR_KEEPASS_CANNOT_DECRYPT_MESSAGE);
173:     }
174: 
175:     const auto key = browserRequest.getString("key");
176:     if (key.isEmpty()) {
177:         return getErrorReply(action, ERROR_KEEPASS_ASSOCIATION_FAILED);
178:     }
179: 
180:     if (key.compare(m_clientPublicKey) == 0) {
181:         // Check for identification key. If it's not found, ensure backwards compatibility and use the current public
182:         // key
183:         const auto idKey = browserRequest.getString("idKey");
184:         const auto id = browserService()->storeKey((idKey.isEmpty() ? key : idKey));
185:         if (id.isEmpty()) {
186:             return getErrorReply(action, ERROR_KEEPASS_ACTION_CANCELLED_OR_DENIED);
187:         }
188: 
189:         m_associated = true;
190: 
191:         auto message = browserMessageBuilder()->buildMessage(browserRequest.incrementedNonce);
192:         message["hash"] = browserRequest.hash;
193:         message["id"] = id;
194:         return buildResponse(action, message, browserRequest.incrementedNonce);
195:     }
196: 
197:     return getErrorReply(action, ERROR_KEEPASS_ASSOCIATION_FAILED);
198: }
