200: QJsonObject BrowserAction::handleTestAssociate(const QJsonObject& json, const QString& action)
201: {
202:     const auto browserRequest = decodeRequest(json);
203:     if (browserRequest.isEmpty()) {
204:         return getErrorReply(action, ERROR_KEEPASS_CANNOT_DECRYPT_MESSAGE);
205:     }
206: 
207:     const auto responseKey = browserRequest.getString("key");
208:     const auto id = browserRequest.getString("id");
209:     if (responseKey.isEmpty() || id.isEmpty()) {
210:         return getErrorReply(action, ERROR_KEEPASS_DATABASE_NOT_OPENED);
211:     }
212: 
213:     const auto key = browserService()->getKey(id);
214:     if (key.isEmpty() || key.compare(responseKey) != 0) {
215:         return getErrorReply(action, ERROR_KEEPASS_ASSOCIATION_FAILED);
216:     }
217: 
218:     m_associated = true;
219: 
220:     auto message = browserMessageBuilder()->buildMessage(browserRequest.incrementedNonce);
221:     message["hash"] = browserRequest.hash;
222:     message["id"] = id;
223: 
224:     return buildResponse(action, message, browserRequest.incrementedNonce);
225: }
